from __future__ import annotations

import re
import unicodedata
from functools import lru_cache
from dataclasses import dataclass


# Runtime contract: this module is imported by phonemizer.py and therefore must
# be present in every immutable Phone Worker release, not only in the VPS checkout.
# Keep the intermediate inventory intentionally close to OpenUtau's Portuguese
# G2P symbols. The worker does not embed OpenUtau/ONNX; this lightweight layer
# exists so orthography is resolved to Portuguese sounds *before* we approximate
# those sounds with a Japanese CV voicebank.
VOWELS = frozenset({"a", "a~", "e", "e~", "E", "i", "i~", "o", "o~", "O", "u", "u~"})
GLIDES = frozenset({"j", "w"})
CONSONANTS = frozenset({
    "b", "d", "dZ", "f", "g", "J", "k", "l", "L", "m", "n", "p",
    "r", "R", "s", "S", "t", "tS", "v", "z", "Z",
})

_PT_VOWEL_CHARS = frozenset("aeiouáéíóúâêôãõàü")
_EXPLICIT_STRESS = frozenset("áéíóúâêôãõ")
_DEFAULT_PENULTIMATE_ENDINGS = ("a", "e", "o", "as", "es", "os", "am", "em", "ens")
_ONSET_CLUSTERS = frozenset({
    ("p", "r"), ("b", "r"), ("t", "r"), ("d", "r"), ("k", "r"), ("g", "r"),
    ("f", "r"), ("v", "r"), ("p", "l"), ("b", "l"), ("k", "l"), ("g", "l"),
    ("f", "l"), ("v", "l"),
})


@dataclass(frozen=True, slots=True)
class Phone:
    symbol: str
    nucleus_index: int | None = None
    stressed: bool = False


@dataclass(frozen=True, slots=True)
class Syllable:
    onset: tuple[str, ...]
    vowel: str
    coda: tuple[str, ...]
    stressed: bool = False


@dataclass(frozen=True, slots=True)
class PhoneticWord:
    source: str
    phones: tuple[Phone, ...]
    syllables: tuple[Syllable, ...]

    @property
    def phonemes(self) -> tuple[str, ...]:
        return tuple(phone.symbol for phone in self.phones)


def _plain(value: str) -> str:
    decomposed = unicodedata.normalize("NFKD", str(value or "").lower())
    return "".join(ch for ch in decomposed if not unicodedata.combining(ch) and ch.isalpha())


def _is_vowel_char(char: str) -> bool:
    return char in _PT_VOWEL_CHARS


def _base_vowel(char: str) -> str:
    if char in "aáàâ":
        return "a"
    if char == "ã":
        return "a~"
    if char in "eê":
        return "e"
    if char == "é":
        return "E"
    if char in "ií":
        return "i"
    if char in "oô":
        return "o"
    if char == "ó":
        return "O"
    if char == "õ":
        return "o~"
    if char in "uúü":
        return "u"
    return "a"


def _nasalize(symbol: str) -> str:
    return {
        "a": "a~", "e": "e~", "E": "e~", "i": "i~",
        "o": "o~", "O": "o~", "u": "u~",
    }.get(symbol, symbol)


def _next_letter(value: str, index: int) -> str:
    return value[index + 1] if index + 1 < len(value) else ""


def _previous_letter(value: str, index: int) -> str:
    return value[index - 1] if index > 0 else ""


def _orthographic_nuclei(value: str) -> list[int]:
    """Return approximate written vowel nuclei for stress placement.

    Adjacent vowels are not automatically one nucleus: accented second vowels
    such as ``aí``/``aú`` are hiatuses, while the high-frequency diphthongs
    handled by :func:`_emit_vowel` stay together.
    """
    starts: list[int] = []
    index = 0
    while index < len(value):
        char = value[index]
        if not _is_vowel_char(char):
            index += 1
            continue
        starts.append(index)
        nxt = value[index + 1] if index + 1 < len(value) else ""
        pair = _plain(char + nxt) if nxt and _is_vowel_char(nxt) else ""
        nasal_pair = char + nxt
        if nxt and nxt not in _EXPLICIT_STRESS and (pair in {"ai", "ei", "oi", "ui", "au", "eu", "iu", "ou"} or nasal_pair in {"ão", "ãe", "õe"}):
            index += 2
        else:
            index += 1
    return starts


def _stress_nucleus(value: str, nucleus_count: int) -> int | None:
    if nucleus_count <= 0:
        return None
    starts = _orthographic_nuclei(value)
    if not starts:
        return None

    explicit_group: int | None = None
    for group_index, start in enumerate(starts):
        end = starts[group_index + 1] if group_index + 1 < len(starts) else len(value)
        # Stop this group's span at the first consonant after it.
        for pos in range(start, end):
            if value[pos] in _EXPLICIT_STRESS:
                explicit_group = group_index
                break
        if explicit_group is not None:
            break

    if explicit_group is None:
        plain = _plain(value)
        if len(starts) > 1 and plain.endswith(_DEFAULT_PENULTIMATE_ENDINGS):
            explicit_group = len(starts) - 2
        else:
            explicit_group = len(starts) - 1

    # Diphthongs collapse two orthographic vowels into one phonetic nucleus, so
    # scale the written group index onto the produced nucleus sequence.
    if len(starts) <= 1 or nucleus_count <= 1:
        return 0
    return max(0, min(nucleus_count - 1, round(explicit_group * (nucleus_count - 1) / (len(starts) - 1))))


def _emit_vowel(value: str, index: int) -> tuple[list[str], int]:
    char = value[index]
    symbol = _base_vowel(char)
    next_char = _next_letter(value, index)
    after_next = value[index + 2] if index + 2 < len(value) else ""

    # Canonical nasal diphthongs first.
    pair = char + next_char
    if pair in {"ão", "Ão", "ÃO"}:
        return ["a~", "w"], 2
    if pair in {"ãe", "Ãe", "ÃE"}:
        return ["a~", "j"], 2
    if pair in {"õe", "Õe", "ÕE"}:
        return ["o~", "j"], 2

    # A vowel followed by coda m/n is nasal in neutral Brazilian Portuguese.
    # Do not consume the n of 'nh'.
    if next_char and next_char in "mn" and not (next_char == "n" and after_next == "h"):
        if not after_next or not _is_vowel_char(after_next):
            return [_nasalize(symbol)], 2

    # Frequent oral diphthongs. Represent the second element as a glide rather
    # than another full nucleus; this is critical when later approximating with
    # a CV bank because the glide can be rendered very short.
    plain_pair = _plain(pair)
    second_is_stressed = next_char in _EXPLICIT_STRESS
    if not second_is_stressed and plain_pair in {"ai", "ei", "oi", "ui"}:
        return [symbol, "j"], 2
    if not second_is_stressed and plain_pair in {"au", "eu", "iu"}:
        return [symbol, "w"], 2
    if not second_is_stressed and plain_pair == "ou":
        # Neutral PT-BR commonly monophthongizes 'ou'. Avoid an extra Japanese
        # vowel unless an explicit pronunciation layer is introduced later.
        return [symbol], 2

    return [symbol], 1


def _scan_phones(word: str) -> list[str]:
    value = unicodedata.normalize("NFC", str(word or "").lower())
    value = re.sub(r"[^a-zàáâãçéêíóôõúü]", "", value)
    phones: list[str] = []
    index = 0
    while index < len(value):
        char = value[index]
        nxt = _next_letter(value, index)
        nxt2 = value[index + 2] if index + 2 < len(value) else ""
        prev = _previous_letter(value, index)

        if _is_vowel_char(char):
            emitted, consumed = _emit_vowel(value, index)
            phones.extend(emitted)
            index += consumed
            continue

        pair = char + nxt
        if pair == "nh":
            phones.append("J")
            index += 2
            continue
        if pair == "lh":
            phones.append("L")
            index += 2
            continue
        if pair == "ch":
            phones.append("S")
            index += 2
            continue
        if pair == "rr":
            phones.append("R")
            index += 2
            continue
        if pair == "ss":
            phones.append("s")
            index += 2
            continue
        if pair == "qu" and nxt2 and nxt2 in "eiéêí":
            phones.append("k")
            index += 2
            continue
        if pair == "gu" and nxt2 and nxt2 in "eiéêí":
            phones.append("g")
            index += 2
            continue
        if pair in {"sc", "sç", "xc"} and nxt2 and nxt2 in "eiéêí":
            phones.append("s")
            index += 2
            continue

        if char == "b":
            phones.append("b")
        elif char == "ç":
            phones.append("s")
        elif char == "c":
            phones.append("s" if nxt and nxt in "eiéêí" else "k")
        elif char == "d":
            # In much of Brazil /d/ palatalizes before an /i/ realization,
            # including final unstressed -de.
            phones.append("dZ" if (nxt and nxt in "ií") or (nxt == "e" and index + 2 == len(value)) else "d")
        elif char == "f":
            phones.append("f")
        elif char == "g":
            phones.append("Z" if nxt and nxt in "eiéêí" else "g")
        elif char == "h":
            pass
        elif char == "j":
            phones.append("Z")
        elif char in "kq":
            phones.append("k")
        elif char == "l":
            # Coda /l/ in Brazilian Portuguese is commonly vocalized to /w/.
            phones.append("w" if not nxt or not _is_vowel_char(nxt) else "l")
        elif char == "m":
            phones.append("m")
        elif char == "n":
            phones.append("n")
        elif char == "p":
            phones.append("p")
        elif char == "r":
            phones.append("R" if index == 0 or prev in "nls" else "r")
        elif char == "s":
            phones.append("z" if _is_vowel_char(prev) and _is_vowel_char(nxt) else "s")
        elif char == "t":
            phones.append("tS" if (nxt and nxt in "ií") or (nxt == "e" and index + 2 == len(value)) else "t")
        elif char == "v":
            phones.append("v")
        elif char == "w":
            phones.append("w")
        elif char == "x":
            # X is highly lexical in Portuguese. These two high-confidence
            # contexts cover exame/exato and word-initial x; other cases use /S/
            # rather than pretending a certainty the lightweight G2P does not have.
            if index == 1 and value.startswith("e") and _is_vowel_char(nxt):
                phones.append("z")
            else:
                phones.append("S")
        elif char == "y":
            phones.append("j")
        elif char == "z":
            phones.append("s" if not nxt else "z")
        index += 1

    return phones


def _reduce_final_unstressed(phones: list[str], stressed_nucleus: int | None) -> list[str]:
    nucleus_positions = [index for index, symbol in enumerate(phones) if symbol in VOWELS]
    if not nucleus_positions:
        return phones
    final_pos = nucleus_positions[-1]
    final_nucleus = len(nucleus_positions) - 1
    if final_nucleus == stressed_nucleus:
        return phones
    output = list(phones)
    if output[final_pos] == "e":
        output[final_pos] = "i"
    elif output[final_pos] == "o":
        output[final_pos] = "u"
    return output


def _restore_final_nasal_glide(
    word: str, phones: list[str], stressed_nucleus: int | None,
) -> list[str]:
    """Keep the nasal diphthong in stressed -em/-ém and plural -ens.

    Applying this to every written -em would also change unstressed verb
    endings. Keep those unchanged until the G2P has a lexical/morphological
    pronunciation layer rather than guessing their realization from spelling.
    """
    value = unicodedata.normalize("NFC", str(word or "").lower())
    if not value.endswith(("em", "ém", "ens", "éns")):
        return phones
    nuclei = [index for index, symbol in enumerate(phones) if symbol in VOWELS]
    if not nuclei or phones[nuclei[-1]] != "e~":
        return phones
    if not value.endswith(("ens", "éns")) and stressed_nucleus != len(nuclei) - 1:
        return phones
    output = list(phones)
    output.insert(nuclei[-1] + 1, "j")
    return output


def _syllabify(symbols: list[str], stressed_nucleus: int | None) -> tuple[Syllable, ...]:
    nucleus_positions = [index for index, symbol in enumerate(symbols) if symbol in VOWELS]
    if not nucleus_positions:
        return ()

    syllables: list[Syllable] = []
    previous_nucleus = -1
    for nucleus_number, nucleus_pos in enumerate(nucleus_positions):
        between = symbols[previous_nucleus + 1:nucleus_pos]
        if nucleus_number == 0:
            onset = tuple(between)
            previous_coda: tuple[str, ...] = ()
        else:
            # Reassign consonants between two nuclei: the largest legal PT onset
            # goes forward, everything else closes the previous syllable.
            if len(between) >= 2 and tuple(between[-2:]) in _ONSET_CLUSTERS:
                split = len(between) - 2
            elif between:
                split = len(between) - 1
            else:
                split = 0
            previous_coda = tuple(between[:split])
            onset = tuple(between[split:])
            if previous_coda:
                prev = syllables[-1]
                syllables[-1] = Syllable(prev.onset, prev.vowel, prev.coda + previous_coda, prev.stressed)

        next_nucleus = nucleus_positions[nucleus_number + 1] if nucleus_number + 1 < len(nucleus_positions) else len(symbols)
        # Glides directly following the vowel belong to this syllable. Other
        # consonants are temporarily left for the next iteration/coda split.
        coda: list[str] = []
        cursor = nucleus_pos + 1
        while cursor < next_nucleus and symbols[cursor] in GLIDES:
            coda.append(symbols[cursor])
            cursor += 1
        syllables.append(Syllable(
            onset=onset,
            vowel=symbols[nucleus_pos],
            coda=tuple(coda),
            stressed=nucleus_number == stressed_nucleus,
        ))
        previous_nucleus = nucleus_pos + len(coda)

    # Remaining phones after the last nucleus are the final coda. Because
    # previous_nucleus may include diphthong glides, avoid duplicating them.
    last_nucleus = nucleus_positions[-1]
    trailing = symbols[last_nucleus + 1:]
    glide_prefix = 0
    while glide_prefix < len(trailing) and trailing[glide_prefix] in GLIDES:
        glide_prefix += 1
    remaining = tuple(trailing[glide_prefix:])
    if remaining:
        prev = syllables[-1]
        syllables[-1] = Syllable(prev.onset, prev.vowel, prev.coda + remaining, prev.stressed)
    return tuple(syllables)


def g2p_word(word: str, *, deaccented: bool = False) -> PhoneticWord:
    source = unicodedata.normalize("NFC", str(word or "")).strip()
    symbols = _scan_phones(source)
    nucleus_count = sum(symbol in VOWELS for symbol in symbols)
    stressed_nucleus = None if deaccented else _stress_nucleus(source.lower(), nucleus_count)
    symbols = _reduce_final_unstressed(symbols, stressed_nucleus)
    symbols = _restore_final_nasal_glide(source, symbols, stressed_nucleus)

    phones: list[Phone] = []
    nucleus = -1
    for symbol in symbols:
        if symbol in VOWELS:
            nucleus += 1
            phones.append(Phone(symbol, nucleus_index=nucleus, stressed=nucleus == stressed_nucleus))
        else:
            phones.append(Phone(symbol, nucleus_index=None, stressed=False))
    syllables = _syllabify([phone.symbol for phone in phones], stressed_nucleus)
    return PhoneticWord(source=source, phones=tuple(phones), syllables=syllables)


_ENGLISH_VOWELS = frozenset({"A", "{", "V", "@", "O", "aI", "aU", "E", "3", "eI", "I", "i", "oU", "OI", "U", "u"})
_ENGLISH_ONSET_CLUSTERS = frozenset({
    ("p", "r"), ("b", "r"), ("t", "r"), ("d", "r"), ("k", "r"), ("g", "r"),
    ("f", "r"), ("T", "r"), ("S", "r"), ("p", "l"), ("b", "l"), ("k", "l"),
    ("g", "l"), ("f", "l"), ("s", "l"), ("s", "m"), ("s", "n"), ("s", "p"),
    ("s", "t"), ("s", "k"), ("s", "w"), ("t", "w"), ("k", "w"), ("g", "w"),
    ("s", "p", "r"), ("s", "t", "r"), ("s", "k", "r"), ("s", "p", "l"),
    ("s", "k", "l"), ("s", "k", "w"),
})
_ARPABET_VOWELS = {
    "AA": "A", "AE": "{", "AH": "V", "AO": "O", "AW": "aU", "AY": "aI",
    "EH": "E", "ER": "3", "EY": "eI", "IH": "I", "IY": "i", "OW": "oU",
    "OY": "OI", "UH": "U", "UW": "u",
}
_ARPABET_CONSONANTS = {
    "B": "b", "CH": "tS", "D": "d", "DH": "D", "F": "f", "G": "g",
    "HH": "h", "JH": "dZ", "K": "k", "L": "l", "M": "m", "N": "n",
    "NG": "N", "P": "p", "R": "r", "S": "s", "SH": "S", "T": "t",
    "TH": "T", "V": "v", "W": "w", "Y": "j", "Z": "z", "ZH": "Z",
}
_ENGLISH_LETTER_NAMES = {
    "a": "EY1", "b": "B IY1", "c": "S IY1", "d": "D IY1", "e": "IY1",
    "f": "EH1 F", "g": "JH IY1", "h": "EY1 CH", "i": "AY1", "j": "JH EY1",
    "k": "K EY1", "l": "EH1 L", "m": "EH1 M", "n": "EH1 N", "o": "OW1",
    "p": "P IY1", "q": "K Y UW1", "r": "AA1 R", "s": "EH1 S", "t": "T IY1",
    "u": "Y UW1", "v": "V IY1", "w": "D AH1 B AH0 L Y UW0", "x": "EH1 K S",
    "y": "W AY1", "z": "Z IY1",
}


@lru_cache(maxsize=1)
def _english_dictionary() -> dict[str, str]:
    """Decode CMUdict only when an English request needs it, entirely offline."""
    import base64
    import zlib

    data = zlib.decompress(base64.b85decode(_CMUDICT_PACKED)).decode("ascii")
    return dict(line.split(" ", 1) for line in data.splitlines())


def _english_syllabify(symbols: list[str], stressed: set[int]) -> tuple[Syllable, ...]:
    positions = [index for index, symbol in enumerate(symbols) if symbol in _ENGLISH_VOWELS]
    if not positions:
        return ()
    syllables: list[Syllable] = []
    previous = -1
    for number, position in enumerate(positions):
        between = symbols[previous + 1:position]
        if number == 0:
            onset = tuple(between)
        else:
            # Maximal legal English onset; /N/ remains a coda, never an onset.
            onset_size = int(bool(between) and between[-1] != "N")
            for size in (2, 3):
                if len(between) >= size and tuple(between[-size:]) in _ENGLISH_ONSET_CLUSTERS:
                    onset_size = size
            split = len(between) - onset_size
            prev = syllables[-1]
            syllables[-1] = Syllable(prev.onset, prev.vowel, tuple(between[:split]), prev.stressed)
            onset = tuple(between[split:])
        syllables.append(Syllable(onset, symbols[position], (), number in stressed))
        previous = position
    last = syllables[-1]
    syllables[-1] = Syllable(last.onset, last.vowel, tuple(symbols[positions[-1] + 1:]), last.stressed)
    return tuple(syllables)


def _english_inflected_pronunciation(word: str, lexicon: dict[str, str]) -> str | None:
    """Use a known stem for regular OOV inflections before spelling rules."""
    for ending in ("'s", "ing", "ed", "es", "s"):
        if not word.endswith(ending) or len(word) <= len(ending) + 1:
            continue
        stem = word[:-len(ending)]
        candidates = [stem]
        if ending in {"ing", "ed"}:
            candidates.append(stem + "e")
            if len(stem) >= 2 and stem[-1] == stem[-2]:
                candidates.append(stem[:-1])
        if ending in {"es", "ed"} and stem.endswith("i"):
            candidates.append(stem[:-1] + "y")
        pronunciation = next((lexicon[key] for key in candidates if key in lexicon), None)
        if pronunciation is None:
            continue
        last = pronunciation.split()[-1]
        if ending == "ing":
            suffix = "IH0 NG"
        elif ending == "ed":
            suffix = "IH0 D" if last in {"T", "D"} else "T" if last in {"P", "K", "F", "S", "SH", "CH", "TH"} else "D"
        else:
            suffix = "IH0 Z" if last in {"S", "Z", "SH", "ZH", "CH", "JH"} else "S" if last in {"P", "T", "K", "F", "TH"} else "Z"
        return pronunciation + " " + suffix
    return None


def _english_oov_symbols(word: str) -> list[str]:
    """Conservative English spelling fallback for names and unseen words.

    This is approximate: it is never passed through Portuguese spelling rules.
    Dictionary pronunciations remain authoritative for irregular English words.
    """
    value = re.sub(r"[^a-z]", "", _plain(word))
    if not value:
        return []
    digraphs = {
        "tion": ("S", "@", "n"), "sion": ("Z", "@", "n"),
        "tch": ("tS",), "dge": ("dZ",), "igh": ("aI",),
        "sh": ("S",), "ch": ("tS",), "th": ("T",), "ph": ("f",),
        "ng": ("N",), "ck": ("k",), "wh": ("w",), "qu": ("k", "w"),
        "ee": ("i",), "ea": ("i",), "oo": ("u",), "oa": ("oU",),
        "ai": ("eI",), "ay": ("eI",), "ei": ("eI",), "ey": ("eI",),
        "oi": ("OI",), "oy": ("OI",), "ou": ("aU",), "ow": ("aU",),
        "au": ("O",), "aw": ("O",), "er": ("3", "r"), "ir": ("3", "r"),
        "ur": ("3", "r"), "ar": ("A", "r"), "or": ("O", "r"),
    }
    short_vowels = {"a": "{", "e": "E", "i": "I", "o": "A", "u": "V"}
    long_vowels = {"a": "eI", "e": "i", "i": "aI", "o": "oU", "u": "u"}
    consonants = {"b": "b", "d": "d", "f": "f", "h": "h", "j": "dZ", "k": "k", "l": "l", "m": "m", "n": "n", "p": "p", "q": "k", "r": "r", "s": "s", "t": "t", "v": "v", "w": "w", "z": "z"}
    result: list[str] = []
    silent_e = len(value) > 2 and value.endswith("e") and value[-2] not in "aeiou"
    index = 0
    if value.startswith(("kn", "gn", "wr")):
        index = 1
    while index < len(value):
        if silent_e and index == len(value) - 1:
            break
        match = next((chunk for chunk in digraphs if value.startswith(chunk, index)), None)
        if match:
            result.extend(digraphs[match])
            index += len(match)
            continue
        char = value[index]
        nxt = value[index + 1:index + 2]
        if char in short_vowels:
            long = silent_e and index == len(value) - 3
            result.append((long_vowels if long else short_vowels)[char])
        elif char == "c":
            result.append("s" if nxt in {"e", "i", "y"} else "k")
        elif char == "g":
            result.append("dZ" if nxt in {"e", "i", "y"} else "g")
        elif char == "x":
            result.extend(("k", "s"))
        elif char == "y":
            result.append("j" if index == 0 else "i" if index == len(value) - 1 else "I")
        elif char in consonants:
            result.append(consonants[char])
        index += 2 if nxt == char and char not in short_vowels else 1
    if not any(symbol in _ENGLISH_VOWELS for symbol in result):
        # English vowelless abbreviations are spoken as letter names.
        return _english_from_arpabet(" ".join(_ENGLISH_LETTER_NAMES[letter] for letter in value))[0]
    return result


def _english_from_arpabet(pronunciation: str) -> tuple[list[str], set[int]]:
    symbols: list[str] = []
    primary: set[int] = set()
    secondary: set[int] = set()
    nucleus = 0
    for phone in pronunciation.split():
        base = phone.rstrip("012")
        if base in _ARPABET_VOWELS:
            stress = phone[-1] if phone[-1:] in {"0", "1", "2"} else "0"
            symbol = "@" if base == "AH" and stress == "0" else _ARPABET_VOWELS[base]
            if base == "ER" and stress == "0":
                symbol = "@"
            symbols.append(symbol)
            if stress == "1":
                primary.add(nucleus)
            elif stress == "2":
                secondary.add(nucleus)
            nucleus += 1
            if base == "ER":
                symbols.append("r")
        elif base in _ARPABET_CONSONANTS:
            symbols.append(_ARPABET_CONSONANTS[base])
    return symbols, primary or secondary


def g2p_english_word(word: str, *, deaccented: bool = False) -> PhoneticWord:
    """US English CMUdict pronunciation, then regular inflections/OOV rules."""
    source = unicodedata.normalize("NFC", str(word or "")).strip().replace("’", "'")
    key = source.lower()
    lexicon = _english_dictionary()
    pronunciation = lexicon.get(key)
    if pronunciation is None and source.isupper() and 1 < len(source) <= 8 and source.isalpha():
        pronunciation = " ".join(_ENGLISH_LETTER_NAMES[letter] for letter in key if letter in _ENGLISH_LETTER_NAMES)
    if pronunciation is None:
        pronunciation = _english_inflected_pronunciation(key, lexicon)
    if pronunciation:
        symbols, stressed = _english_from_arpabet(pronunciation)
    else:
        symbols = _english_oov_symbols(key)
        stressed = {0} if any(symbol in _ENGLISH_VOWELS for symbol in symbols) else set()
    if deaccented:
        stressed = set()
    phones: list[Phone] = []
    nucleus = -1
    for symbol in symbols:
        if symbol in _ENGLISH_VOWELS:
            nucleus += 1
            phones.append(Phone(symbol, nucleus, nucleus in stressed))
        else:
            phones.append(Phone(symbol))
    return PhoneticWord(source, tuple(phones), _english_syllabify(symbols, stressed))


_ENGLISH_SMALL_NUMBERS = (
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
    "seventeen", "eighteen", "nineteen",
)
_ENGLISH_TENS = ("", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety")


def _english_integer(value: int) -> str:
    if value < 20:
        return _ENGLISH_SMALL_NUMBERS[value]
    if value < 100:
        return _ENGLISH_TENS[value // 10] + (" " + _english_integer(value % 10) if value % 10 else "")
    for scale, name in ((10**12, "trillion"), (10**9, "billion"), (10**6, "million"), (1000, "thousand"), (100, "hundred")):
        if value >= scale:
            return _english_integer(value // scale) + " " + name + (" " + _english_integer(value % scale) if value % scale else "")
    return ""


def expand_english_numbers(text: str) -> str:
    """Read integer/decimal digits in English instead of dropping them."""
    def expand(match: re.Match[str]) -> str:
        value = match.group()
        negative = value.startswith("-")
        value = value.lstrip("-")
        whole, dot, fraction = value.partition(".")
        if len(whole) > 15 or (len(whole) > 1 and whole.startswith("0")):
            spoken = " ".join(_ENGLISH_SMALL_NUMBERS[int(digit)] for digit in whole)
        else:
            spoken = _english_integer(int(whole))
        if dot:
            spoken += " point " + " ".join(_ENGLISH_SMALL_NUMBERS[int(digit)] for digit in fraction)
        return ("minus " if negative else "") + spoken

    normalized = re.sub(r"(?<!\d)\d{1,3}(?:,\d{3})+(?!\d)", lambda match: match.group().replace(",", ""), str(text or ""))
    return re.sub(r"(?<![\w])-?\d+(?:\.\d+)?", expand, normalized)


